function validate(input) {
  const [{ Failed = [], Succeeded = [] }] = input;
  const seen = new Map();
  for (const [table, rows] of [['Failed', Failed], ['Succeeded', Succeeded]]) {
    for (const [d] of rows) {
      if (d === null) return `Every ${table} row needs a date.`;
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) return `${d} is not a YYYY-MM-DD date.`;
      if (seen.get(d) === table) return `${d} appears twice in ${table}.`;
      if (seen.has(d)) return `${d} is both a failed and a succeeded day.`;
      seen.set(d, table);
    }
  }
  return null;
}

