function generate(rand, size) {
  const iso = (base, k) => new Date(base + k * 86400000).toISOString().slice(0, 10);
  const Failed = [], Succeeded = [];
  let base, span, cap;
  if (size === 'small') {
    const anchors = [Date.UTC(2018, 11, 27), Date.UTC(2019, 1, 24), Date.UTC(2019, 6, 1), Date.UTC(2019, 11, 25)];
    base = anchors[Math.floor(rand() * anchors.length)];
    span = Math.floor(rand() * 12);
    cap = 8;
  } else {
    base = Date.UTC(2018, 10, 1);
    span = 520;
    cap = 2000;
  }
  // A run-based walk: each day usually keeps the previous outcome, sometimes switches or is left unrecorded.
  let state = rand() < 0.5 ? 'F' : 'S';
  for (let k = 0; k < span; k++) {
    const r = rand();
    if (r < 0.15) continue;
    if (r < 0.45) state = state === 'F' ? 'S' : 'F';
    const day = iso(base, k);
    if (state === 'F' && Failed.length < cap) Failed.push([day]);
    else if (state === 'S' && Succeeded.length < cap) Succeeded.push([day]);
  }
  return [{ Failed, Succeeded }];
}
